"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Textarea } from "@/components/ui/textarea"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Label } from "@/components/ui/label"

export default function HomePage() {
  const [question, setQuestion] = useState("")
  const [answer, setAnswer] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const router = useRouter()

  const handleAnalyze = async () => {
    if (!question.trim() || !answer.trim()) return

    setIsLoading(true)
    try {
      const response = await fetch("/api/analyze-intent", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question, answer }),
      })

      const data = await response.json()

      // Store result in sessionStorage to pass to result page
      sessionStorage.setItem(
        "analysisResult",
        JSON.stringify({
          ...data,
          question,
          answer,
        }),
      )

      router.push("/result")
    } catch (error) {
      console.error("Analysis failed:", error)
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <main className="min-h-screen bg-background py-12 px-4">
      <div className="max-w-3xl mx-auto">
        <div className="text-center mb-10">
          <h1 className="text-3xl font-serif font-semibold text-foreground mb-2">
            AQMD – Answer–Question Mismatch Detector
          </h1>
          <p className="text-muted-foreground">Checks whether the answer actually addresses the question's intent.</p>
        </div>

        <Card className="glass-card animate-float">
          <CardHeader>
            <CardTitle className="font-serif text-2xl">Analyze Answer Intent</CardTitle>
            <CardDescription className="text-base">
              Enter the question and student answer below to detect potential mismatches.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="question" className="text-sm font-medium">
                Question
              </Label>
              <Textarea
                id="question"
                placeholder="Enter the question here..."
                className="min-h-[120px] resize-none"
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="answer" className="text-sm font-medium">
                Student Answer
              </Label>
              <Textarea
                id="answer"
                placeholder="Enter the student's answer here..."
                className="min-h-[160px] resize-none"
                value={answer}
                onChange={(e) => setAnswer(e.target.value)}
              />
            </div>

            <Button
              onClick={handleAnalyze}
              disabled={!question.trim() || !answer.trim() || isLoading}
              className="w-full"
              size="lg"
            >
              {isLoading ? "Analyzing with AI..." : "Analyze Answer Intent"}
            </Button>
          </CardContent>
        </Card>

        <div className="mt-6 text-center">
          <a
            href="/history"
            className="text-sm text-muted-foreground hover:text-foreground underline-offset-4 hover:underline"
          >
            View Analysis History
          </a>
        </div>
      </div>
    </main>
  )
}
